import { useLocation } from 'react-router-dom';
import { MarketplaceBrowsePage } from '../components/marketplace/MarketplaceBrowsePage';
import type { MarketplaceCategoryKey } from '../types/marketplace';

const categoryPages: Record<
  string,
  {
    type: MarketplaceCategoryKey;
    title: string;
    description: string;
  }
> = {
  '/digital-products': {
    type: 'digital-products',
    title: 'Digital products',
    description:
      'Discover published templates, ebooks, software, downloads and creative assets from independent sellers.',
  },
  '/services': {
    type: 'services',
    title: 'Expert services',
    description:
      'Compare published services from designers, developers, marketers and other independent experts.',
  },
  '/courses': {
    type: 'courses',
    title: 'Courses',
    description:
      'Explore published courses, workshops and coaching offers with clear pricing and access details.',
  },
  '/communities': {
    type: 'communities',
    title: 'Communities',
    description:
      'Find published groups and memberships built around shared goals, skills and interests.',
  },
};

export const MarketplaceCategory = () => {
  const { pathname } = useLocation();
  const page = categoryPages[pathname] || categoryPages['/digital-products'];
  return (
    <MarketplaceBrowsePage
      title={page.title}
      description={page.description}
      canonicalPath={pathname}
      fixedType={page.type}
      eyebrow="Browse the marketplace"
    />
  );
};
